#!/usr/bin/env python3
"""Generate the synthetic W-1 Excel fixture corpus (PRD §4, §4.1, CU-PLUGIN-11).

Deterministic, stdlib-only (zipfile + hand-written minimal OOXML) so the
corpus can be regenerated byte-stably on any OS. Every workbook is the
EXPECTED post-format state: leading zeros, long IDs and formula-like values
are stored as inline strings, the way the host's Text formatting leaves them.

Output: test/fixtures/w1/workbooks/*.xlsx + manifest.json enumerating every
case, its split, and the count of missing W-1 matrix cells.
"""

from __future__ import annotations

import hashlib
import json
import random
import zipfile
from pathlib import Path

HERE = Path(__file__).resolve().parent
WORKBOOKS = HERE / "workbooks"

HEADERS_EN = ["Full Name", "Email", "Phone", "Postal Code", "Member ID", "Notes"]
HEADERS_ZH = ["姓名", "电子邮件", "电话", "邮政编码", "会员编号", "备注"]


def col_letter(index: int) -> str:
    name = ""
    while index >= 0:
        name = chr(ord("A") + index % 26) + name
        index = index // 26 - 1
    return name


def sheet_xml(rows: list[list[object]]) -> str:
    """Minimal worksheet: inline strings for text, plain numbers otherwise."""
    body = []
    for r, row in enumerate(rows, start=1):
        cells = []
        for c, value in enumerate(row):
            ref = f"{col_letter(c)}{r}"
            if isinstance(value, (int, float)):
                cells.append(f'<c r="{ref}"><v>{value}</v></c>')
            else:
                text = (
                    str(value)
                    .replace("&", "&amp;")
                    .replace("<", "&lt;")
                    .replace(">", "&gt;")
                )
                cells.append(f'<c r="{ref}" t="inlineStr"><is><t>{text}</t></is></c>')
        body.append(f'<row r="{r}">{"".join(cells)}</row>')
    return (
        '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
        '<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">'
        f'<sheetData>{"".join(body)}</sheetData></worksheet>'
    )


def workbook_xml(sheet_name: str) -> str:
    return (
        '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
        '<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" '
        'xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships">'
        f'<sheets><sheet name="{sheet_name}" sheetId="1" r:id="rId1"/></sheets></workbook>'
    )


CONTENT_TYPES = (
    '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
    '<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">'
    '<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>'
    '<Default Extension="xml" ContentType="application/xml"/>'
    '<Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>'
    '<Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>'
    "</Types>"
)

ROOT_RELS = (
    '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
    '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
    '<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/>'
    "</Relationships>"
)

WORKBOOK_RELS = (
    '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
    '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
    '<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/>'
    "</Relationships>"
)


def write_xlsx(path: Path, rows: list[list[object]], sheet_name: str = "Sheet1") -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    with zipfile.ZipFile(path, "w", zipfile.ZIP_DEFLATED) as archive:
        archive.writestr("[Content_Types].xml", CONTENT_TYPES)
        archive.writestr("_rels/.rels", ROOT_RELS)
        archive.writestr("xl/workbook.xml", workbook_xml(sheet_name))
        archive.writestr("xl/_rels/workbook.xml.rels", WORKBOOK_RELS)
        archive.writestr("xl/worksheets/sheet1.xml", sheet_xml(rows))


def synthetic_rows(count: int, locale: str, rng: random.Random) -> list[list[object]]:
    """Synthetic leads with realistic W-1 edge cases (PRD §4.1 data family)."""
    headers = HEADERS_ZH if locale == "zh-CN" else HEADERS_EN
    rows: list[list[object]] = [headers]
    names_zh = ["张伟", "王芳", "李娜", "刘洋", "陈静", "杨帆", "赵磊", "孙丽"]
    duplicate_email = f"dup{rng.randrange(100, 999)}@example.com"
    for i in range(count):
        member_no = f"MN-{rng.randrange(10**11, 10**12 - 1)}"  # 12-digit ID stays text
        row_index = i + 2  # Excel row number for deterministic values
        if locale == "zh-CN":
            name = names_zh[i % len(names_zh)]
        else:
            name = f"Lead {row_index:04d}"
        email = duplicate_email if i % 37 == 5 else f"lead{row_index:04d}@example.com"
        phone = f"{rng.randrange(100, 999)}-{rng.randrange(100, 999)}-{rng.randrange(1000, 9999)}"  # leading digit never 0 after area, but keep as text anyway
        if i % 53 == 7:
            phone = f"0{rng.randrange(100, 999)}-{rng.randrange(1000, 9999)}"  # explicit leading zero
        postal = f"0{rng.randrange(10000, 99999)}" if i % 29 == 3 else f"{rng.randrange(10000, 99999)}"
        notes = ""
        if i % 41 == 11:
            notes = "=SUM(A1:A2)"  # formula-like: must stay text, never execute
        elif i % 43 == 13:
            notes = "+1 555 0100"  # plus-prefixed: Excel would treat as formula
        rows.append([name, email, phone, postal, member_no, notes])
    return rows


def sha256_file(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def main() -> None:
    rng = random.Random(20260928)  # frozen seed: corpus is reproducible
    cases: list[dict[str, object]] = []

    def case(
        case_id: str,
        filename: str,
        rows: list[list[object]],
        family: str,
        split: str,
        locale: str,
        sheet_name: str = "Sheet1",
    ) -> None:
        path = WORKBOOKS / filename
        write_xlsx(path, rows, sheet_name)
        cases.append(
            {
                "id": case_id,
                "workbook": f"workbooks/{filename}",
                "sha256": sha256_file(path),
                "bytes": path.stat().st_size,
                "family": family,
                "split": split,
                "locale": locale,
                "rowCount": max(0, len(rows) - 1),
                "headerRow": rows[0] if rows else [],
                "fullExpected": rows[1:],
                "consentClass": "synthetic",
            }
        )

    # --- Workbook layout family (PRD §4.1 row 1) ---
    case("w1-empty-template", "empty-template.xlsx", [HEADERS_EN], "layout", "regression", "en-US")
    case("w1-empty-template-zh", "empty-template-zh.xlsx", [HEADERS_ZH], "layout", "regression", "zh-CN")
    populated_20_rows = synthetic_rows(20, "en-US", rng)
    populated_20_body = populated_20_rows[1:]
    for count, split in ((20, "regression"), (200, "calibration"), (500, "held_out")):
        case(
            f"w1-populated-{count}",
            f"populated-{count}.xlsx",
            populated_20_rows if count == 20 else synthetic_rows(count, "en-US", rng),
            "layout",
            split,
            "en-US",
        )
    case(
        "w1-populated-200-zh",
        "populated-200-zh.xlsx",
        synthetic_rows(200, "zh-CN", rng),
        "layout",
        "regression",
        "zh-CN",
    )
    case(
        "w1-populated-20-zh",
        "populated-20-zh.xlsx",
        synthetic_rows(20, "zh-CN", rng),
        "layout",
        "regression",
        "zh-CN",
    )
    case(
        "w1-populated-500-zh",
        "populated-500-zh.xlsx",
        synthetic_rows(500, "zh-CN", rng),
        "layout",
        "held_out",
        "zh-CN",
    )
    reordered = [HEADERS_EN[2], HEADERS_EN[0], HEADERS_EN[1], *HEADERS_EN[3:]]
    body = populated_20_body
    case(
        "w1-reordered-headers",
        "reordered-headers.xlsx",
        [reordered, *[ [r[2], r[0], r[1], *r[3:]] for r in body ]],
        "layout",
        "regression",
        "en-US",
    )
    duplicate_headers = HEADERS_EN[:2] + [HEADERS_EN[1]] + HEADERS_EN[2:]
    case(
        "w1-duplicate-header",
        "duplicate-header.xlsx",
        [duplicate_headers, *body],
        "layout",
        "regression",
        "en-US",
    )
    unmatched = HEADERS_EN[:-1] + ["Region"]  # Notes missing, Region unmatched
    case(
        "w1-unmatched-field",
        "unmatched-field.xlsx",
        [unmatched, *[r[:-1] + [""] for r in body]],
        "layout",
        "regression",
        "en-US",
    )

    # --- Data-preservation family at every scale/locale (matrix completion) ---
    def preservation_rows(locale: str, count: int) -> list[list[object]]:
        headers = HEADERS_ZH if locale == "zh-CN" else HEADERS_EN
        edge: list[list[object]] = [
            ["张伟", "zhang.wei@example.com", "010-5555", "02138", "MN-000123456789", ""],
            ["O'Brien", "dup@example.com", "0911-2020", "08540", "MN-000987654321", "=SUM(A1:A2)"],
            ["Anne", "dup@example.com", "+1 555 0100", "90210", "123456789012345678", "+1 555 0100"],
            ["李娜", "li.na@example.com", "021-6789", "01234", "MN-000555000555", "'=NOT_A_FORMULA"],
        ]
        if locale == "zh-CN":
            edge = edge + [["王芳", "wang.fang@example.com", "0571-8888", "100000", "MN-000777000777", "+86 138 0000"]]
        body = [row[:] for row in edge]
        index = 0
        while len(body) < count:
            template = body[index % len(edge)][:]
            template[1] = f"cycled{index:04d}@example.com"
            body.append(template)
            index += 1
        return [headers] + body[:count]

    for locale, suffix in (("en-US", ""), ("zh-CN", "-zh")):
        for count, split in ((20, "regression"), (200, "calibration"), (500, "held_out")):
            case(
                f"w1-data-preservation-{count}{suffix}",
                f"data-preservation-{count}{suffix}.xlsx",
                preservation_rows(locale, count),
                "data-preservation",
                split,
                locale,
            )

    # --- Matrix completeness accounting (PRD §4: manifest counts missing cells) ---
    planned_matrix = {
        "layout": ["empty-template", "populated-20", "populated-200", "populated-500",
                   "reordered-headers", "duplicate-header", "unmatched-field"],
        "locale": ["en-US", "zh-CN"],
        "rowCount": [0, 20, 200, 500],
        "data-preservation": [
            "leading-zero-phone", "leading-zero-postal", "long-id", "cjk-name",
            "duplicate-email", "formula-like-equals", "formula-like-plus",
        ],
    }
    present = {(c["family"], c["locale"], c["rowCount"]) for c in cases}
    missing: list[str] = []
    for locale in planned_matrix["locale"]:
        for count in planned_matrix["rowCount"]:
            for family in ("layout", "data-preservation"):
                if (family, locale, count) not in present and count != 0:
                    missing.append(f"{family}/{locale}/{count}rows")
    # Enrich the planned list so it names the now-covered cells too.
    planned_matrix["nowCovered"] = sorted(f"{f}/{l}/{r}" for f, l, r in present)

    manifest = {
        "version": 1,
        "datasetId": "w1-workbooks",
        "generator": "test/fixtures/w1/generate.py (seed 20260928)",
        "cases": cases,
        "matrixAccounting": {
            "planned": planned_matrix,
            "missingCells": missing,
            "missingCellCount": len(missing),
        },
        "notes": "Workbooks are the expected post-format state (Text formatting applied). "
                 "Vision/geometry/native-state/handoff fixture families from PRD §4.1 need "
                 "real captures and stay pending the native spikes.",
    }
    (HERE / "manifest.json").write_text(json.dumps(manifest, indent=2, ensure_ascii=False) + "\n")
    print(f"wrote {len(cases)} workbooks; missing matrix cells: {len(missing)}")


if __name__ == "__main__":
    main()
